#!/usr/bin/env bash
# Collects the VOC reruns. Failures go to voc_collect.log; stops only at a pass, or when nothing is left to collect.
cd /scratch2/exaFLOPs/srl_yam_run/pipe
for i in $(seq 1 1400); do sleep 60; left=0; while read n t c a v; do [ -f .vcollected_$n ] && continue; left=$((left+1)); [ -z "$(squeue -h -j $v -o %i 2>/dev/null)" ] || continue; L=vv$n-$v.log; touch .vcollected_$n; EP=$(printf recon_%06d $n); RN=${EP}_voc; if [ -f $L ] && grep -q VIDEO_DONE $L; then OUT=$(RN=$RN VT=-voc ./collect.sh $n); else OUT="ep$n no videos (job $v)"; fi; echo "$(date +%H:%M) $OUT" >> voc_collect.log; python3 voc_show.py $n $RN >> voc_collect.log; if echo "$OUT" | grep -q PASS; then echo "$OUT"; python3 voc_show.py $n $RN; date; exit 0; fi; done < voc_rerun.ids; [ -s restart.ids ] && [ "$(ls .rs_* 2>/dev/null | wc -l)" = 4 ] && [ $left = 0 ] && break; done; echo ALL_COLLECTED; cat voc_collect.log | tail -30; date
